if (!requireNamespace("BiocManager", quietly = TRUE)) {
  install.packages("BiocManager")
}
BiocManager::install(c("GenomicFeatures", "AnnotationDbi"))

# What is the class of A? --> matrix
class(A)  

# What is the class of friends_data? --> data.frame
class(friends_data)

trial <- data.frame(
  treatment = rep(c("Control", "Compost"), each = 4),
  yield_t_ha = c(3.1, 3.4, 3.2, 3.5, 3.9, 4.1, 3.8, 4.2)
)
aggregate(yield_t_ha ~ treatment, trial,
          function(x) c(n = length(x), mean = mean(x), sd = sd(x)))

if (knitr::is_html_output()) {
  plotly::ggplotly(scatter)
} else {
  scatter
}
dir.create("outputs", showWarnings = FALSE)
